// Native WebGL integration of Portal Field; no external runtime or CDN needed.
(()=>{const canvas=document.querySelector('#portal-field'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let gl,program,buffer,raf=0,w=0,h=0,last=0,elapsed=0;const mouse={x:.5,y:.5},target={x:.5,y:.5};
try{gl=canvas.getContext('webgl',{alpha:true,antialias:false,powerPreference:'low-power'});if(!gl)throw Error('WebGL unavailable');const compile=(type,source)=>{const shader=gl.createShader(type);gl.shaderSource(shader,source);gl.compileShader(shader);if(!gl.getShaderParameter(shader,gl.COMPILE_STATUS))throw Error('Portal shader failed');return shader};const vertex=compile(gl.VERTEX_SHADER,'attribute vec2 a_position; varying vec2 vUv; void main(){vUv=a_position*.5+.5;gl_Position=vec4(a_position,0.,1.);}'),fragment=compile(gl.FRAGMENT_SHADER,window.PLAB_PORTAL_FRAGMENT);program=gl.createProgram();gl.attachShader(program,vertex);gl.attachShader(program,fragment);gl.linkProgram(program);gl.deleteShader(vertex);gl.deleteShader(fragment);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('Portal link failed');gl.useProgram(program);buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);const p=gl.getAttribLocation(program,'a_position');gl.enableVertexAttribArray(p);gl.vertexAttribPointer(p,2,gl.FLOAT,false,0,0);const loc={};for(const key of ['time','resolution','mouse','colorCore','colorFringe','isLightMode'])loc[key]=gl.getUniformLocation(program,'u_'+key);gl.uniform3f(loc.colorCore,.75,.88,1);gl.uniform3f(loc.colorFringe,.025,.13,.5);gl.uniform1f(loc.isLightMode,0);
function resize(){const dpr=Math.min(devicePixelRatio||1,1.5);w=Math.round(innerWidth*dpr);h=Math.round(innerHeight*dpr);canvas.width=w;canvas.height=h;gl.viewport(0,0,w,h);draw(performance.now())}
function draw(now){if(gl.isContextLost())return;const dt=last?Math.min((now-last)/1000,.05):0;last=now;if(!reduced.matches)elapsed+=dt*.65;mouse.x+=(target.x-mouse.x)*.03;mouse.y+=(target.y-mouse.y)*.03;gl.uniform1f(loc.time,elapsed);gl.uniform2f(loc.resolution,w,h);gl.uniform2f(loc.mouse,reduced.matches?.5:mouse.x,reduced.matches?.5:mouse.y);gl.drawArrays(gl.TRIANGLE_STRIP,0,4)}
function frame(now){raf=0;if(document.hidden)return;draw(now);if(!reduced.matches)raf=requestAnimationFrame(frame)}function restart(){cancelAnimationFrame(raf);last=0;if(!document.hidden){draw(performance.now());if(!reduced.matches)raf=requestAnimationFrame(frame)}}
addEventListener('resize',resize);addEventListener('pointermove',e=>{target.x=e.clientX/innerWidth;target.y=1-e.clientY/innerHeight},{passive:true});document.addEventListener('visibilitychange',restart);reduced.addEventListener('change',restart);canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(raf);canvas.style.display='none';document.body.classList.remove('portal-ready')});addEventListener('pagehide',()=>{cancelAnimationFrame(raf);gl.deleteBuffer(buffer);gl.deleteProgram(program)});resize();document.body.classList.add('portal-ready');restart();
}catch(error){canvas.style.display='none'}})();
